describe('Table Column Sort Direction Indicator', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display arrow icon to indicate sort direction when column is sorted', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify column headers are present
    cy.get('[data-testid="column-header-name"]').should('be.visible');
    cy.get('[data-testid="column-header-email"]').should('be.visible');

    // Click on column header to sort
    cy.get('[data-testid="column-header-name"]').click();

    // Verify arrow icon appears next to column header
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('be.visible');

    // Verify arrow icon indicates ascending sort (up arrow)
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('have.class', 'sort-arrow-up');

    // Verify table data is sorted
    cy.get('[data-testid="table-row"]').first().should('contain', 'Alice');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Zoe');

    // Click again to sort in descending order
    cy.get('[data-testid="column-header-name"]').click();

    // Verify arrow icon changes to descending sort (down arrow)
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('have.class', 'sort-arrow-down');

    // Verify table data is sorted in descending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Zoe');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Alice');
  });

  it('should remove arrow icon when column is not sorted', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify arrow icon is not visible initially
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('not.exist');

    // Verify arrow icon is not visible on other columns
    cy.get('[data-testid="column-header-email"]').find('[data-testid="sort-arrow-icon"]').should('not.exist');

    // Click on column header to sort
    cy.get('[data-testid="column-header-name"]').click();

    // Verify arrow icon appears
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('be.visible');

    // Click on column header again to sort in descending order
    cy.get('[data-testid="column-header-name"]').click();

    // Verify arrow icon is still visible
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('be.visible');

    // Click on a different column header to sort
    cy.get('[data-testid="column-header-email"]').click();

    // Verify arrow icon appears on the new column
    cy.get('[data-testid="column-header-email"]').find('[data-testid="sort-arrow-icon"]').should('be.visible');

    // Verify arrow icon on the previous column is removed
    cy.get('[data-testid="column-header-name"]').find('[data-testid="sort-arrow-icon"]').should('not.exist');
  });
});
